import os
import csv
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20191204", "20191205", "20191206"]
res = {}
for d in dates:
    p = DIR / f"{d}_pipeline.csv"
    day = {}
    with open(p, encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row["管道划分"] in ("西气东输二线", "西气东输三线"):
                day[row["管道划分"]] = day.get(row["管道划分"], Decimal(0)) + Decimal(row["管道流量"])
    res[d] = day

for line in ("西气东输二线", "西气东输三线"):
    tot = sum(res[d][line] for d in dates)
    print(line, [str(res[d][line]) for d in dates], "total=", tot)

diff = sum(res[d]["西气东输二线"] for d in dates) - sum(res[d]["西气东输三线"] for d in dates)
print("diff(二线-三线)=", diff)

import os
import csv
from pathlib import Path
from decimal import Decimal

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20190124", "20190125", "20190126"]
lines = ["冀宁线", "西气东输一线"]

daily = {d: {l: Decimal("0") for l in lines} for d in dates}
counts = {d: {l: 0 for l in lines} for d in dates}

for d in dates:
    with open(DIR / f"{d}_pipeline.csv", newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            name = row["管道划分"].strip()
            if name in lines:
                daily[d][name] += Decimal(row["管道流量"])
                counts[d][name] += 1

for d in dates:
    print(d, {l: str(daily[d][l]) for l in lines}, counts[d])

tot = {l: sum(daily[d][l] for d in dates) for l in lines}
print("total", {l: str(tot[l]) for l in lines})
print("diff", str(tot["西气东输一线"] - tot["冀宁线"]))

