import os, json
from pathlib import Path
from collections import deque

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
csv_path = DIR / "20190114_pipeline.csv"

rows = []
with open(csv_path, newline="", encoding="utf-8-sig") as f:
    import csv as _csv
    reader = _csv.DictReader(f)
    for r in reader:
        rows.append(r)

print("columns:", list(rows[0].keys()) if rows else None)
print("row_count:", len(rows))

# Identify source/target/pipeline columns heuristically
cols = list(rows[0].keys())
def find_col(cands):
    for c in cols:
        if any(k in c.lower() for k in cands):
            return c
    return None

src_col = find_col(["source", "start", "from", "起点", "源"])
tgt_col = find_col(["target", "end", "to", "终点", "目的"])
pipe_col = find_col(["pipeline", "line", "管段", "管线"])
print("src_col:", src_col, "tgt_col:", tgt_col, "pipe_col:", pipe_col)

# Build directed adjacency (gas flow direction) and undirected fallback
adj = {}
uadj = {}
for r in rows:
    s, t, p = r[src_col], r[tgt_col], r[pipe_col]
    adj.setdefault(s, []).append((t, p))
    uadj.setdefault(s, []).append((t, p))
    uadj.setdefault(t, []).append((s, p))

def bfs(graph, start, goal):
    if start == goal:
        return [start]
    prev = {start: None}
    q = deque([start])
    while q:
        u = q.popleft()
        for v, p in graph.get(u, []):
            if v not in prev:
                prev[v] = (u, p)
                if v == goal:
                    path = [v]
                    while prev[path[-1]] is not None:
                        u2, p2 = prev[path[-1]]
                        path.append((u2, p2))
                    path.reverse()
                    return path
                q.append(v)
    return None

def fmt(path):
    if not path:
        return None
    out = [path[0]]
    for item in path[1:]:
        if isinstance(item, tuple):
            out.append(item[0])
    return out

def fmt_edges(path):
    if not path:
        return []
    edges = []
    for i in range(len(path) - 1):
        a = path[i]
        b = path[i + 1]
        p = b[1] if isinstance(b, tuple) else None
        edges.append({"source": a, "target": b[0] if isinstance(b, tuple) else b, "pipeline": p})
    return edges

TARGET = "南通站"
SOURCES = ["靖边站", "榆林站", "黑河首站", "霍尔果斯首站"]

result = {}
for s in SOURCES:
    dp = bfs(adj, s, TARGET)
    up = bfs(uadj, s, TARGET)
    result[s] = {
        "directed_path": fmt(dp),
        "directed_edges": fmt_edges(dp),
        "undirected_path": fmt(up),
        "undirected_edges": fmt_edges(up),
    }

print(json.dumps(result, ensure_ascii=False, indent=2))

