import os
import csv
from pathlib import Path
from collections import defaultdict

DIR = Path(os.environ["PIPELINE_FLOW_DIR"])
dates = ["20191203", "20191204", "20191205", "20191206", "20191207"]
targets = ["川气东送", "西气东输二线"]

# daily[pipeline][date] = list of segment flows
daily = {p: defaultdict(list) for p in targets}
row_counts = {p: defaultdict(int) for p in targets}

for d in dates:
    path = DIR / f"{d}_pipeline.csv"
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            pipe = (row.get("管道划分") or "").strip()
            if pipe in targets:
                try:
                    flow = float(row["管道流量"])
                except (KeyError, ValueError):
                    continue
                daily[pipe][d].append(flow)
                row_counts[pipe][d] += 1

result = {}
for p in targets:
    daily_avg = {}
    for d in dates:
        flows = daily[p][d]
        daily_avg[d] = sum(flows) / len(flows) if flows else None
    vals = [v for v in daily_avg.values() if v is not None]
    result[p] = {
        "daily_avg": {k: round(v, 3) if v is not None else None for k, v in daily_avg.items()},
        "rows_per_day": {d: row_counts[p][d] for d in dates},
        "mean_of_daily_avg": round(sum(vals) / len(vals), 3),
        "range_of_daily_avg": round(max(vals) - min(vals), 3),
        "min_daily_avg": round(min(vals), 3),
        "max_daily_avg": round(max(vals), 3),
    }

import json
print(json.dumps(result, ensure_ascii=False, indent=2, default=str))

